import java.util.Scanner;

public class P_B_Text_Document_Analysis {
    static int outsideMax(String s, int from, int to) {
        int max = 0;
        int cur = 0;
        for (int i = from; i < to; i++) {
            char c = s.charAt(i);
            if (c != '_' && c != ')') {
                cur++;
                if (cur > max) {
                    max = cur;
                }
            } else {
                cur = 0;
            }
        }
        return max;
    }

    static int insideWords(String s, int from, int to) {
        int words = 0;
        int i = from;
        while (i < to) {
            char c = s.charAt(i);
            if (c != '_' && c != '(' && c != ')') {
                words++;
                while (i < to && s.charAt(i) != '_'
                        && s.charAt(i) != '(' && s.charAt(i) != ')') {
                    i++;
                }
            } else {
                i++;
            }
        }
        return words;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int stringLen = scanner.nextInt();
        String text = scanner.next();
        scanner.close();

        int outMax = 0;
        int inMax = 0;
        int i = 0;

        while (i < text.length()) {
            int open = text.indexOf('(', i);
            int end = (open == -1) ? text.length() : open;

            int m = outsideMax(text, i, end);
            if (m > outMax) {
                outMax = m;
            }

            if (open == -1) {
                break;
            }

            int close = text.indexOf(')', open + 1);
            if (close == -1) {
                inMax += insideWords(text, open + 1, text.length());
                break;
            } else {
                inMax += insideWords(text, open + 1, close);
                i = close + 1;
            }
        }

        System.out.print(outMax + " " + inMax);
    }
}
